                "content": "import SidebarGroup from \"../../components/ui/sidebar/group.marko\";\nimport Label from \"../../components/ui/label/label.marko\";\nimport Input from \"../../components/ui/input/input.marko\";\n\n<form>\n  <SidebarGroup class=\"py-0\">\n    <div class=\"relative\">\n      <Label for=\"search\" class=\"sr-only\">Search</Label>\n      <Input id=\"search\" placeholder=\"Search the docs...\" class=\"pl-8\"/>\n      <svg\n        xmlns=\"http://www.w3.org/2000/svg\"\n        width=\"24\"\n        height=\"24\"\n        viewBox=\"0 0 24 24\"\n        fill=\"none\"\n        stroke=\"currentColor\"\n        stroke-width=\"2\"\n        stroke-linecap=\"round\"\n        stroke-linejoin=\"round\"\n        class=\"pointer-events-none absolute top-1/2 left-2 size-4 -translate-y-1/2 text-muted-foreground select-none\"\n      >\n        <circle cx=\"11\" cy=\"11\" r=\"8\"/>\n        <path d=\"m21 21-4.3-4.3\"/>\n      </svg>\n    </div>\n  </SidebarGroup>\n</form>\n"
