                "content": "import Button from \"../../components/ui/button/button.marko\";\nimport FieldGroup from \"../../components/ui/field/field-group.marko\";\nimport FieldLabel from \"../../components/ui/field/field-label.marko\";\nimport FieldDescription from \"../../components/ui/field/field-description.marko\";\nimport FieldSeparator from \"../../components/ui/field/field-separator.marko\";\nimport Input from \"../../components/ui/input/input.marko\";\nimport { cn } from \"../../lib/utils.ts\";\n\nexport interface Input extends Marko.Input<\"div\"> {}\n\n<const/{ class: className, content: _content, ...rest }=input/>\n\n<div ...rest class=cn(\"flex flex-col gap-6\", className)>\n  <form>\n    <FieldGroup>\n      <div class=\"flex flex-col items-center gap-2 text-center\">\n        <a href=\"#\" class=\"flex flex-col items-center gap-2 font-medium\">\n          <div class=\"flex size-8 items-center justify-center rounded-md\">\n            <svg\n              xmlns=\"http://www.w3.org/2000/svg\"\n              viewBox=\"0 0 24 24\"\n              fill=\"none\"\n              stroke=\"currentColor\"\n              stroke-width=\"2\"\n              stroke-linecap=\"round\"\n              stroke-linejoin=\"round\"\n              class=\"size-6\"\n            >\n              <path d=\"M2 12h10\"/>\n              <path d=\"M9 4v16\"/>\n              <path d=\"M14 9h8\"/>\n              <path d=\"M14 5h8\"/>\n              <path d=\"M14 13h8\"/>\n              <path d=\"M14 17h8\"/>\n            </svg>\n          </div>\n          <span class=\"sr-only\">Acme Inc.</span>\n        </a>\n        <h1 class=\"text-xl font-bold\">Welcome to Acme Inc.</h1>\n        <FieldDescription>\n          Already have an account? <a href=\"#\">Sign in</a>\n        </FieldDescription>\n      </div>\n      <div data-slot=\"field\">\n        <FieldLabel for=\"signup-05-email\">Email</FieldLabel>\n        <Input id=\"signup-05-email\" name=\"email\" type=\"email\" placeholder=\"m@example.com\" required/>\n      </div>\n      <div data-slot=\"field\">\n        <Button type=\"submit\">Create Account</Button>\n      </div>\n      <FieldSeparator>Or</FieldSeparator>\n      <div data-slot=\"field\" class=\"grid gap-4 sm:grid-cols-2\">\n        <Button variant=\"outline\" type=\"button\">\n          <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\">\n            <path\n              d=\"M12.152 6.896c-.948 0-2.415-1.078-3.96-1.04-2.04.027-3.91 1.183-4.961 3.014-2.117 3.675-.546 9.103 1.519 12.09 1.013 1.454 2.208 3.09 3.792 3.039 1.52-.065 2.09-.987 3.935-.987 1.831 0 2.35.987 3.96.948 1.637-.026 2.676-1.48 3.676-2.948 1.156-1.688 1.636-3.325 1.662-3.415-.039-.013-3.182-1.221-3.22-4.857-.026-3.04 2.48-4.494 2.597-4.559-1.429-2.09-3.623-2.324-4.39-2.376-2-.156-3.675 1.09-4.61 1.09zM15.53 3.83c.843-1.012 1.4-2.427 1.245-3.83-1.207.052-2.662.805-3.532 1.818-.78.896-1.454 2.338-1.273 3.714 1.338.104 2.715-.688 3.559-1.701\"\n              fill=\"currentColor\"\n            />\n          </svg>\n          Continue with Apple\n        </Button>\n        <Button variant=\"outline\" type=\"button\">\n          <svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 24 24\">\n            <path\n              d=\"M12.48 10.92v3.28h7.84c-.24 1.84-.853 3.187-1.787 4.133-1.147 1.147-2.933 2.4-6.053 2.4-4.827 0-8.6-3.893-8.6-8.72s3.773-8.72 8.6-8.72c2.6 0 4.507 1.027 5.907 2.347l2.307-2.307C18.747 1.44 16.133 0 12.48 0 5.867 0 .307 5.387.307 12s5.56 12 12.173 12c3.573 0 6.267-1.173 8.373-3.36 2.16-2.16 2.84-5.213 2.84-7.667 0-.76-.053-1.467-.173-2.053H12.48z\"\n              fill=\"currentColor\"\n            />\n          </svg>\n          Continue with Google\n        </Button>\n      </div>\n    </FieldGroup>\n  </form>\n  <FieldDescription class=\"px-6 text-center\">\n    By clicking continue, you agree to our <a href=\"#\">Terms of Service</a>\n    and <a href=\"#\">Privacy Policy</a>.\n  </FieldDescription>\n</div>\n"
